    DB_SHIP = "aus Beiträgen (%d Spieler), Stand Build %s",
    OPT_dataCollect = "Datenbank: Erlebtes sammeln",
    OPT_dataCollect_TIP = "Merkt sich kontoweit, was deine Charaktere erleben – Beute je Gegner, Händler und Lehrer, Fundorte, Eingänge, Gegnerstufen. Nur Nummern und Zahlen, nie Namen anderer Spieler. Gespeichert wird im Ordner ezWorld; fehlt er, nur bis zum Abmelden. Was ezCore schon immer für dich merkt (Händler, Lehrer, Rezepte, Dauer deiner Buffs), merkt es auch, wenn der Schalter aus ist.",
    -- Beitragen: Spieler » Projekt (DB-N1, Contribute.lua)
    ANON_CHAR = "<Charakter>", ANON_REALM = "<Realm>", ANON_GUILD = "<Gilde>", ANON_PLAYER = "<Spieler>",
    CONTRIB_TITLE = "Mithelfen",
    CONTRIB_HELP_HEAD = "Mithelfen: Deine Entdeckungen helfen allen Spielern. Freiwillig, einmalig, jederzeit abschaltbar.",
    CONTRIB_STEP1 = "1. Die Addons installieren: ezCollection (Ordner ezCore) samt den Ordnern ezWorld und ezMarket – nichts weiter einschalten, die Datenbank sammelt von selbst.",
    CONTRIB_STEP2 = "2. Normal spielen (am besten etwa einen Monat).",
    CONTRIB_STEP3 = "3. „Beitrag vorbereiten“ anklicken (Esc » Optionen » AddOns » ezCollection » Erweitert, oder /ez beitrag), den anonymen Text mit Strg+C kopieren und in ein neues GitHub-Issue im Projekt einfügen:",
    CONTRIB_CONTENT = "Was der Text enthält: nur Weltwissen in Nummern und Zahlen – was Gegner und Behälter fallen ließen, wo Händler, Lehrer, Fundorte und Eingänge sind, Rezepte und Flugzeiten, jeweils mit Build und Tag.",
    CONTRIB_NOT_CONTENT = "Was er nicht enthält: keine Namen von Charakteren, Gilden, Realms oder Mitspielern, kein Konto, keine Realm-Angaben, keine Uhrzeiten, keine Chat- oder Brieftexte, keine Einstellungen. Bereinigt wird im Spiel, bevor du etwas kopierst; „Lesbar zeigen“ zeigt dir, was darin steht. Ablesen lässt sich allenfalls, welche Klasse und Berufe du spielst und an welchen Tagen.",
    CONTRIB_ID = "Dazu kommt eine Zufallskennung deiner Datenbank (%s): Sie sagt nichts über dich, verhindert doppeltes Zählen, und mit ihr kannst du deinen Beitrag zurückziehen.",
    CONTRIB_ATTACH = "Mehr als 60000 Zeichen: im Editor als beitrag.txt speichern und in das Issue ziehen (höchstens 25 MB).",
    CONTRIB_GITHUB = "GitHub zeigt am Issue deinen Kontonamen. Soll er dort nicht stehen, gib den Text jemandem, der ihn für dich einstellt – dann brauchst du auch kein Konto. Die Datei ezWorld.lua selbst bitte nicht anhängen: Sie ist nicht bereinigt.",
    CONTRIB_LICENSE = "Mit dem Schicken räumst du dem Autor nach der Lizenz des Projekts (%s, Abschnitt 3 b) das dauerhafte, weltweite, kostenlose und unwiderrufliche Recht ein, die Daten als Teil von ezCollection zu nutzen, zu ändern, zu veröffentlichen und weiterzugeben, auch unter dieser oder einer späteren Lizenz von ezCollection; du bestätigst, dass du das darfst, und behältst deine eigenen Rechte daran. „Beitrag vorbereiten“ fragt dich vorher.",
    CONTRIB_PROBE = "Zusatz für Freiwillige: /ez probe auto hält zusätzlich fest, was der Client antwortet (Entwicklerwerkzeug). Nur nach Absprache; die Datei dazu (%s) ist nicht bereinigt, nennt deine Charaktere und gehört nie in ein öffentliches Issue.",
    CONTRIB_PATH = "WTF\\Account\\<Konto>\\SavedVariables\\%s.lua",
    CONTRIB_NOT_SAVED = "Die Datenbank wird gerade nicht gespeichert (Träger ezWorld fehlt) – es gibt nichts zu schicken.",
    CONTRIB_ASK = "Beitrag vorbereiten: ezCollection macht aus deiner Datenbank einen anonymen Text – nur Weltwissen in Nummern, keine Namen, kein Konto, keine Uhrzeiten. Du kopierst ihn und schickst ihn selbst (GitHub-Issue), ezCollection verschickt nie etwas. Räumst du dem Autor nach der Lizenz des Projekts (%s, Abschnitt 3 b) das dauerhafte, weltweite, kostenlose und unwiderrufliche Recht ein, die Daten als Teil von ezCollection zu nutzen, zu ändern, zusammenzuführen, zu veröffentlichen und mit auszuliefern, auch unter dieser oder einer späteren Lizenz von ezCollection, und bestätigst du, dass du das darfst? Deine eigenen Rechte daran behältst du.",
