    CHARS_RENAMED_NOTICE = "%s ist wahrscheinlich dieser Charakter vor einer Umbenennung (gleiche Kennung). Gold und Bestände zählen doppelt, bis du ihn unter Esc » Optionen » AddOns » ezCollection » „Bekannte Charaktere“ vergisst.",
    REALM_BY_ID = "Realm Nr. %s",
    GUILDS_HEADER = "Gemerkte Gildenbanken",
    GUILDS_HEADER_TIP = "Jede Gildenbank, die ein eigener Charakter geöffnet hat. Ihr Bestand zählt in Tooltips und Listen mit, solange einer deiner Charaktere in dieser Gilde ist. Ist keiner mehr Mitglied (Austritt, Fraktionswechsel, Twink vergessen), steht „veraltet“ dabei und sie zählt nicht mehr. Ein Twink, der seit dem letzten Update nicht angemeldet war, hält sie nur, wenn er sie selbst erfasst hat oder danach noch angemeldet war („vielleicht veraltet“). „Vergessen“ entfernt sie ganz – nach einer Rückfrage. Eine in dieser Sitzung zum ersten Mal geöffnete Gildenbank steht erst nach /reload hier.",
    GUILDS_NAME_REALM = "%s (%s)",
