    GUILDS_STALE = "veraltet: kein eigener Charakter mehr Mitglied, zählt nicht mit",
    GUILDS_MAYBE = "vielleicht veraltet: zählt mit, bis sich %s anmeldet (Gilde noch unbekannt)",
