    DEBUG_TIP = "Schneidet mit, welche Ereignisse und Nachrichten durch ezCollection laufen und wie lange jeder Zuhörer braucht. Erster Klick startet, zweiter stoppt und zeigt den Bericht zum Kopieren (wie /ez debug). Endet nach fünf Minuten von selbst.",
