    -- Daten-Probe (Probe.lua, ProbeStations.lua)
    OPT_probeAuto = "Daten-Probe: Automatik",
    PROBE_AUTO_BUTTON = "An / Aus",
    OPT_probeAuto_TIP = "Der einfache Weg: einschalten und normal weiterspielen. Die Probe startet dann von selbst die passende Station, sobald ihr Anlass eintritt – Händler, Lehrer, Briefkasten, Auktionshaus, Bank, Flugmeister, Berufefenster, Quest oder Gespräch, Beutefenster, Weltkarte, ein neues Ziel (je Zielart einmal), Kampfbeginn, Gruppe, Dungeon, Tod. Jede Art läuft nur wenige Male je Charakter und je Lage (Freiland, Instanz, Gruppe, Bosskampf; Flugmeister je Kontinent), gezählt über alle Sitzungen; was du schon von Hand erfasst hast, zählt mit – ein zweiter Charakter, ein Dungeon oder ein Bosskampf wird so wieder von selbst erfasst. Dazu nimmt sie Besonderes mit, wenn es vorkommt: Händler mit begrenztem Vorrat, Klassenlehrer, Lehrer mit allen Filtern, Auktionssuche, Beute aus Truhe, Erz, Kraut oder Gegenstand, Angeln, Spielobjekt in Reichweite, Vignette. Beim Einschalten schreibt sie einmal die Dokumentation mit, misst einmal das Tempo (sobald du stehst) und schaltet den Mitschnitt der Ereignisse ein. Sie bleibt an – auch nach /reload und Neuanmeldung –, bis du sie ausschaltest oder die Probe voll ist. Sind alle Arten erfasst, die hier zählen, sagt sie es (einmal je Charakter und Lage), startet hier keine Station mehr und hört nur noch auf Ereignisse, von denen ihr etwas fehlt (Bosskampf, Würfeln um Beute …). Sie rechnet in kleinen Portionen, damit das Spiel nicht ruckelt. Sie liest nur, Namen stehen nie in den Daten, Sonderproben löst sie nie aus. /ez probe zeigt, was noch fehlt (wie /ez probe auto).",
    OPT_probeAutoQuiet = "Daten-Probe: Automatik leise",
    OPT_probeAutoQuiet_TIP = "Die Automatik schreibt nach jeder Station eine kurze Zeile in den Chat („… festgehalten – noch offen: …“). Leise: keine dieser Zeilen – gemeldet werden nur noch das Ein- und Ausschalten, „alles erfasst“ und „Probe voll“ (wie /ez probe auto leise).",
    PROBE_AUTO_ON = "Daten-Probe: Automatik an – spiel einfach normal weiter; %s",
    PROBE_AUTO_ALREADY = "Die Automatik der Daten-Probe läuft schon; %s",
    PROBE_AUTO_OFF = "Daten-Probe: Automatik aus. %s",
    PROBE_AUTO_NOT_ON = "Die Automatik der Daten-Probe ist aus.",
    PROBE_AUTO_WHERE = "(Charakter %d, %s)",
