    PROBE_LAGE_ib = "Bosskampf in einer Instanz", PROBE_LAGE_igb = "Bosskampf in einer Instanz in einer Gruppe",
    PROBE_KIND_B_limited = "Händler mit begrenztem Vorrat", PROBE_KIND_B_cost = "Händler mit Zusatzkosten",
    PROBE_KIND_C_class = "Klassenlehrer", PROBE_KIND_C_prof = "Berufslehrer", PROBE_KIND_C_pet = "Tierausbilder",
    PROBE_KIND_C_all = "Lehrer mit allen Filtern", PROBE_KIND_E_browse = "Auktionssuche",
    PROBE_KIND_E_result = "Ergebniszeilen der Auktionssuche", PROBE_KIND_J_unlearned = "Berufefenster mit „ungelernte zeigen“",
    PROBE_KIND_G10_object = "Beute aus einem Objekt (Truhe, Erz, Kraut)", PROBE_KIND_G10_item = "Beute aus einem Gegenstand (Kiste, Zerlegen)",
    PROBE_KIND_G10_fish = "Beute beim Angeln", PROBE_KIND_O_object = "Spielobjekt in Reichweite", PROBE_KIND_O_vignette = "Vignette",
    PROBE_SAME = "wie zuvor",
    OPT_probeHelper = "Daten-Probe: für Helfer",
    PROBE_HELPER_BUTTON = "Hinweis zeigen",
    OPT_probeHelper_TIP = "Für alle, die beim Sammeln helfen: Automatik an, normal spielen, am Ende /reload – und dann die eine Datei schicken, die der Hinweis im Chat nennt. Die Probe speichert keine Namen; die Datei enthält daneben aber deine übrigen Daten von ezCollection (Charaktere, Gold), das Lese-Werkzeug liest daraus nur die Probe und maskiert dort zusätzlich jeden Namen. Die Kennung im Hinweis ist eine Zufallszahl dieser Installation (kein Name, kein Realm, kein Konto) – so findest du deinen Beitrag im Bericht wieder (wie /ez probe helfer).",
    PROBE_HELPER = "Daten-Probe für Helfer: nach dem Spielen /reload, dann die Datei WTF\\Account\\<Konto>\\SavedVariables\\ezCore.lua schicken – sie enthält auch deine übrigen Daten von ezCollection, das Lese-Werkzeug tools/probe.lua liest daraus nur die Probe und maskiert alle Namen (Kennung dieser Installation: %s).",
    PROBE_HELPER_NEW = "entsteht mit dem ersten Lauf",
    PROBE_AUTO_RESUMED = "Daten-Probe: Die Automatik läuft weiter; %s",
    PROBE_AUTO_DONE = "Daten-Probe (Automatik): %s festgehalten – %s",
    PROBE_AUTO_OPEN = "noch offen (%d): %s",
    PROBE_AUTO_AGAIN = "%s (%d. Lauf)",
    PROBE_AUTO_MORE = " …",
    PROBE_AUTO_ALL = "alle Arten der Stationen erfasst.",
    PROBE_AUTO_SPECIALS = "Sonderproben laufen nicht von selbst: %s",
    PROBE_AUTO_SPECIAL = "%s mit %s",
    PROBE_AUTO_COMPLETE = "Daten-Probe (Automatik): alles erfasst in dieser Lage %s – hier startet sie keine Station mehr; in einer anderen Lage, auf einem anderen Kontinent oder mit einem anderen Charakter geht es weiter. %s%s",
    PROBE_AUTO_WAITING = "Noch nie eingetreten sind %d Ereignisse. Der Mitschnitt hört nur noch auf Ereignisse, von denen etwas fehlt (das kostet nichts, solange sie nicht eintreten); ganz aus: /ez probe auto aus.",
    PROBE_AUTO_WAITING_PROBES = "Noch nie eingetreten sind %d Ereignisse, darunter mit eigener Abfrage: %s. Der Mitschnitt hört nur noch auf Ereignisse, von denen etwas fehlt (das kostet nichts, solange sie nicht eintreten); ganz aus: /ez probe auto aus.",
    PROBE_AUTO_FULL = "Die Daten-Probe ist voll (%s). Die Automatik bleibt an: Sie zählt nur noch und hält nur noch fest, was neu ist. Was du tun kannst: /reload, die Datei schicken, die /ez probe helfer nennt, und erst nach der Rückmeldung „Daten-Probe leeren“.",
    PROBE_AUTO_HARD = "Die Daten-Probe ist ganz voll (%s). Die Automatik bleibt an, zählt aber nur noch – festgehalten wird nichts mehr. Was du tun kannst: /reload, die Datei schicken, die /ez probe helfer nennt, und erst nach der Rückmeldung „Daten-Probe leeren“.",
    PROBE_AUTO_DOC = "Daten-Probe (Automatik): Dokumentation des Clients festgehalten (%d Systeme).",
