    PROBE_AUTO_QUIET_ON = "Daten-Probe: Automatik leise – keine Chatzeile mehr je Station.",
    PROBE_AUTO_QUIET_OFF = "Daten-Probe: Die Automatik meldet wieder jede Station mit einer Zeile.",
    PROBE_AUTO_HEAD = "Automatik: %s – erfasst: %d von %d Arten; %s",
    PROBE_AUTO_STATE_ON = "an", PROBE_AUTO_STATE_QUIET = "an (leise)", PROBE_AUTO_STATE_OFF = "aus",
    PROBE_STATUS_AUTO = "; Automatik an",
    PROBE_STATUS_AUTO_DONE = "; Automatik wartet nur noch auf seltene Ereignisse",
    PROBE_KINDS_LINE = "  Zielarten: %s",
    PROBE_KIND_ITEM = "%s %s",
    PROBE_KIND_TITLE = "Ziel (%s)",
    PROBE_KIND_npc = "freundlicher NPC", PROBE_KIND_enemy = "Gegner", PROBE_KIND_elite = "Elite oder selten",
    PROBE_KIND_player = "Spieler", PROBE_KIND_pet = "Begleiter", PROBE_KIND_corpse = "Leiche",
    OPT_probeHere = "Daten-Probe an dieser Stelle",
    PROBE_HERE_BUTTON = "Probe starten",
    OPT_probeHere_TIP = "Hält fest, was der Client hier wirklich antwortet – für den Bau der Entdecker-Datenbank. Die Probe erkennt selbst, was gerade geht: offenes Fenster (Händler, Lehrer, Briefkasten, Auktionshaus, Bank, Berufe, Flugmeister, Quest, Karte), Ziel, Gruppe, Dungeon, Kampf; ohne all das fragt sie die Grunddaten ab (dauert einige Sekunden). Sie liest nur und ändert nichts. Namen von Charakteren, Gilde, Freunden, Konto und Realm werden nie gespeichert – vom Realm bleibt nur die Nummer (wie /ez probe hier).",
    OPT_probeRest = "Daten-Probe: Restschaden und Restheilung",
    OPT_probeRest_TIP = "Hält etwa zehn Sekunden lang fest, was der Client für Restschaden und Restheilung antwortet: Sperren, Kennungen nur als lesbar oder gesperrt, Treffer je Einheit, ob ein Balken gesperrte Lebenswerte annimmt, Zahlen aus den Beschreibungen deiner DoTs und Heilungen; nach dem Kampf den Schadensmesser. Läuft nur auf Klick, nie von selbst. Für Kämpfe: /ez probe rest (etwa als Makro).",
    OPT_probeRecord = "Daten-Probe: Mitschnitt der Ereignisse",
    PROBE_RECORD_BUTTON = "An / Aus",
    OPT_probeRecord_TIP = "Schneidet mit, welche Ereignisse der Client meldet und wie ihre Werte aufgebaut sind – beim Plündern, Kämpfen, Herstellen, Sammeln, bei Quests und am Flugmeister. Solange er läuft, fragt die Probe bei Beute, Questfenstern und am Flugmeister von selbst nach. Je Mitschnitt hält sie höchstens 500 Ereignisse fest (danach zählt sie nur noch) – am besten je Tätigkeit ein eigener Mitschnitt. Ein Ereignis, von dem sie genug Beispiele hat, zählt sie nur noch. Erster Klick startet, zweiter stoppt (wie /ez probe an und /ez probe aus). Chat-Texte werden nie gespeichert.",
    OPT_probeTempo = "Daten-Probe: Tempo messen",
    PROBE_TEMPO_BUTTON = "Messen / Abbrechen",
    OPT_probeTempo_TIP = "Fragt eine Stichprobe von je 300 Gegenstands- und Zauber-Nummern in kleinen Portionen ab und hält fest, wie viele der Client sofort beantwortet, wie viele er nachlädt, wie viele ohne Antwort bleiben und wie viele Antworten je Sekunde kommen. Nicht im Kampf (dort pausiert die Messung); ein zweiter Klick bricht ab (wie /ez probe tempo).",
    OPT_probeDoc = "Daten-Probe: Dokumentation mitschreiben",
    PROBE_DOC_BUTTON = "Mitschreiben",
    OPT_probeDoc_TIP = "Schreibt Blizzards eingebaute Dokumentation dieses Clients mit (dieselbe, die /api zeigt): Systeme, Funktionen mit Argumenten und Rückgaben, Ereignisse, Tabellen und Aufzählungen – kompakt, etwa 1 bis 2 MB. Lädt dafür Blizzards Dokumentations-Addon nach; nicht im Kampf (wie /ez probe doku).",
    OPT_probeStatus = "Daten-Probe",
    PROBE_STATUS_BUTTON = "Bericht zeigen",
    OPT_probeStatus_TIP = "Zeigt, wie viel die Daten-Probe festgehalten hat (Einträge und Größe in der Datei), und den Bericht zum Kopieren: je Abfrage eine Zeile mit den Feldern und einem Beispielwert, dazu die letzten Ereignisse. Auf der Platte stehen die Daten erst nach /reload oder dem Ausloggen (wie /ez probe status und /ez probe zeigen).",
    OPT_probeClear = "Daten-Probe leeren",
    PROBE_CLEAR_BUTTON = "Probe leeren",
    OPT_probeClear_TIP = "Löscht alles, was die Daten-Probe festgehalten hat (Abfragen, Ereignisse, Tempo-Messungen, Dokumentation) – nach einer Rückfrage. Einstellungen und alle anderen Daten bleiben (wie /ez probe leeren).",
    OPT_probeAuction = "Sonderprobe: Komplett-Scan des Auktionshauses",
    OPT_probeAuction_TIP = "Nur bei offenem Auktionshaus und nur nach Rückfrage: fordert einmal alle Auktionen an und prüft, ob der Server das bedient. Nebenwirkung: Der Server sperrt den Komplett-Scan danach vermutlich für etwa 15 Minuten (wie /ez probe x2).",
    OPT_probeWaypoint = "Sonderprobe: Wegpunkt",
    OPT_probeWaypoint_TIP = "Nur nach Rückfrage: setzt kurz einen Wegpunkt auf die eigene Position, liest Link und Entfernung und stellt danach den alten Wegpunkt und die Zielverfolgung wieder her (wie /ez probe x3).",
    OPT_probeRecipes = "Sonderprobe: ungelernte Rezepte",
    OPT_probeRecipes_TIP = "Nur bei offenem Berufefenster und nur nach Rückfrage: schaltet Blizzards Filter „ungelernte zeigen“ kurz ein, zählt die Rezepte und stellt ihn sofort zurück (wie /ez probe x4).",
    OPT_probeInspect = "Sonderprobe: Spieler betrachten",
    OPT_probeInspect_TIP = "Nur mit einem Spieler als Ziel und nur nach Rückfrage: fragt beim Server dessen Ausrüstung und Talente an (wie „Betrachten“) und hält den Aufbau der Antwort fest – ohne Namen (wie /ez probe betrachten).",
