    SPELLCHECK_TIP = "Fragt den Client nach jeder Zauber-ID, die ezCollection führt: Name, Symbol, ob es sie gibt, ab welcher Stufe man sie lernt und ob dein Charakter sie kennt. Das Ergebnis steht danach in einem Kopierfeld zum Schicken und im Speicher von ezCore (ohne Charaktername). Wie /ez zauber.",
    SPELLCHECK_TITLE = "Zauber-Prüfung",
