    CONTRIB_TITLE = "Help out",
    CONTRIB_HELP_HEAD = "Help out: your discoveries help every player. Voluntary, once, can be switched off any time.",
    CONTRIB_STEP1 = "1. Install the addons: ezCollection (folder ezCore) together with the folders ezWorld and ezMarket – nothing else to switch on, the database collects by itself.",
    CONTRIB_STEP2 = "2. Play normally (ideally for about a month).",
    CONTRIB_STEP3 = "3. Click “Prepare contribution” (Esc » Options » AddOns » ezCollection » Advanced, or /ez contribute), copy the anonymous text with Ctrl+C and paste it into a new GitHub issue of the project:",
    CONTRIB_CONTENT = "What the text contains: world knowledge only, as numbers – what enemies and containers dropped, where vendors, trainers, gathering spots and entrances are, recipes and flight times, each with build and day.",
    CONTRIB_NOT_CONTENT = "What it does not contain: no names of characters, guilds, realms or other players, no account, no realm details, no times of day, no chat or mail texts, no settings. The game cleans it before there is anything to copy; “Show readable” lets you see what is in it. At most it reveals which class and professions you play and on which days.",
    CONTRIB_ID = "Added is a random ID of your database (%s): it says nothing about you, prevents double counting, and with it you can withdraw your contribution.",
    CONTRIB_ATTACH = "More than 60000 characters: save it as beitrag.txt in a text editor and drag it into the issue (25 MB at most).",
    CONTRIB_GITHUB = "GitHub shows your account name on the issue. If it should not appear there, give the text to someone who posts it for you – then you need no account either. Please do not attach the file ezWorld.lua itself: it is not cleaned.",
    CONTRIB_LICENSE = "By sending it you grant the author, under the project's license (%s, section 3 b), a permanent, worldwide, free and irrevocable right to use, change, publish and pass on the data as part of ezCollection, also under this or any later license of ezCollection; you confirm you are allowed to do so and keep your own rights in it. \"Prepare contribution\" asks you first.",
