    -- Data probe (Probe.lua, ProbeStations.lua)
    OPT_probeAuto = "Data probe: automatic",
    PROBE_AUTO_BUTTON = "On / off",
    OPT_probeAuto_TIP = "The easy way: switch it on and keep playing as usual. The probe then starts the fitting station by itself as soon as its occasion comes up – merchant, trainer, mailbox, auction house, bank, flight master, profession window, quest or gossip, loot window, world map, a new target (once per kind of target), start of combat, group, dungeon, death. Each kind runs only a few times per character and per situation (open world, instance, group, boss fight; flight master per continent), counted across all sessions; what you already recorded by hand counts too – so a second character, a dungeon or a boss fight is recorded again by itself. It also takes along special cases when they come up: merchant with limited stock, class trainer, trainer with all filters, auction search, loot from a chest, ore, herb or item, fishing, game object in reach, vignette. When switched on it records the documentation once, measures the speed once (as soon as you stand still) and switches on the event recording. It stays on – also after /reload and logging in again – until you switch it off or the probe is full. Once every kind that counts here is recorded it says so (once per character and situation), starts no more stations here and only listens to events it still lacks something of (boss fight, rolling for loot …). It works in small portions so the game does not stutter. It only reads, names never appear in the data, and it never starts a special probe. /ez probe shows what is still missing (like /ez probe auto).",
    OPT_probeAutoQuiet = "Data probe: quiet automatic",
    OPT_probeAutoQuiet_TIP = "After each station the automatic writes one short line to the chat (“… recorded – still open: …”). Quiet: none of these lines – only switching on and off, “everything recorded” and “probe full” are still reported (like /ez probe auto quiet).",
    PROBE_AUTO_ON = "Data probe: automatic on – just keep playing; %s",
    PROBE_AUTO_ALREADY = "The automatic of the data probe is already running; %s",
    PROBE_AUTO_OFF = "Data probe: automatic off. %s",
    PROBE_AUTO_NOT_ON = "The automatic of the data probe is off.",
    PROBE_AUTO_WHERE = "(character %d, %s)",
