    PROBE_LAGE_wgb = "boss fight in the open world in a group", PROBE_LAGE_i = "instance", PROBE_LAGE_ig = "instance in a group",
    PROBE_LAGE_ib = "boss fight in an instance", PROBE_LAGE_igb = "boss fight in an instance in a group",
    PROBE_KIND_B_limited = "merchant with limited stock", PROBE_KIND_B_cost = "merchant with extra costs",
    PROBE_KIND_C_class = "class trainer", PROBE_KIND_C_prof = "profession trainer", PROBE_KIND_C_pet = "pet trainer",
    PROBE_KIND_C_all = "trainer with all filters", PROBE_KIND_E_browse = "auction search",
