    PROBE_KIND_G10_object = "loot from an object (chest, ore, herb)", PROBE_KIND_G10_item = "loot from an item (box, salvage)",
    PROBE_KIND_G10_fish = "loot from fishing", PROBE_KIND_O_object = "game object in reach", PROBE_KIND_O_vignette = "vignette",
    PROBE_SAME = "as before",
    OPT_probeHelper = "Data probe: for helpers",
    PROBE_HELPER_BUTTON = "Show hint",
    OPT_probeHelper_TIP = "For everyone helping to collect: automatic on, play as usual, /reload at the end – then send the one file the hint in the chat names. The probe stores no names; besides it, the file holds your other ezCollection data (characters, gold), the reader takes only the probe from it and additionally masks every name there. The ID in the hint is a random number of this installation (no name, no realm, no account) – so you find your contribution in the report again (like /ez probe helper).",
    PROBE_HELPER = "Data probe for helpers: after playing, /reload, then send the file WTF\\Account\\<Account>\\SavedVariables\\ezCore.lua – it also holds your other ezCollection data, the reader tools/probe.lua takes only the probe from it and masks all names (ID of this installation: %s).",
