    PROBE_AUTO_SPECIALS = "Special probes do not run by themselves: %s",
    PROBE_AUTO_SPECIAL = "%s with %s",
    PROBE_AUTO_COMPLETE = "Data probe (automatic): everything recorded in this situation %s – it starts no more stations here; in another situation, on another continent or with another character it carries on. %s%s",
    PROBE_AUTO_WAITING = "%d events have never occurred. The event recording only listens to events it still lacks something of (that costs nothing while they do not occur); to switch it off completely: /ez probe auto off.",
    PROBE_AUTO_WAITING_PROBES = "%d events have never occurred, among them with a query of their own: %s. The event recording only listens to events it still lacks something of (that costs nothing while they do not occur); to switch it off completely: /ez probe auto off.",
