    PROBE_AUTO_HARD = "The data probe is completely full (%s). The automatic stays on but only counts – nothing more is recorded. What you can do: /reload, send the file /ez probe helper names, and only after the reply “Clear data probe”.",
    PROBE_AUTO_DOC = "Data probe (automatic): the documentation of the client is recorded (%d systems).",
    PROBE_AUTO_TEMPO_START = "Data probe (automatic): measuring the speed – best stand still for a moment. /ez probe tempo cancels.",
    PROBE_AUTO_TEMPO = "Data probe (automatic): speed measured.",
    PROBE_AUTO_QUIET_ON = "Data probe: quiet automatic – no more chat line per station.",
    PROBE_AUTO_QUIET_OFF = "Data probe: the automatic reports each station with one line again.",
    PROBE_AUTO_HEAD = "Automatic: %s – recorded: %d of %d kinds; %s",
