    PROBE_KIND_TITLE = "Target (%s)",
    PROBE_KIND_npc = "friendly NPC", PROBE_KIND_enemy = "enemy", PROBE_KIND_elite = "elite or rare",
    PROBE_KIND_player = "player", PROBE_KIND_pet = "pet", PROBE_KIND_corpse = "corpse",
    OPT_probeHere = "Data probe at this spot",
    PROBE_HERE_BUTTON = "Start probe",
    OPT_probeHere_TIP = "Records what the client really answers here – for building the explorer database. The probe finds out by itself what is possible right now: open window (merchant, trainer, mailbox, auction house, bank, professions, flight master, quest, map), target, group, dungeon, combat; without any of these it asks for the basic data (takes a few seconds). It only reads and changes nothing. Names of characters, guild, friends, account and realm are never stored – of the realm only its number is kept (like /ez probe here).",
    OPT_probeRest = "Data probe: remaining damage and healing",
    OPT_probeRest_TIP = "Records for about ten seconds what the client answers for remaining damage and healing: restrictions, identifiers only as readable or locked, hits per unit, whether a bar accepts locked health values, numbers from the descriptions of your DoTs and heals; after combat the damage meter. Runs only on click, never by itself. For fights: /ez probe rest (for example as a macro).",
    OPT_probeRecord = "Data probe: event recording",
    PROBE_RECORD_BUTTON = "On / off",
    OPT_probeRecord_TIP = "Records which events the client reports and how their values are built – while looting, fighting, crafting, gathering, questing and at the flight master. While it runs, the probe asks by itself at loot, quest windows and the flight master. Each recording keeps at most 500 events (after that it only counts) – best use one recording per activity. An event it has enough samples of is only counted. The first click starts, the second stops (like /ez probe on and /ez probe off). Chat texts are never stored.",
    OPT_probeTempo = "Data probe: measure speed",
    PROBE_TEMPO_BUTTON = "Measure / cancel",
    OPT_probeTempo_TIP = "Asks for a sample of 300 item and 300 spell numbers in small portions and records how many the client answers at once, how many it loads later, how many stay unanswered and how many answers arrive per second. Not in combat (the measurement pauses there); a second click cancels (like /ez probe tempo).",
    OPT_probeDoc = "Data probe: record the documentation",
    PROBE_DOC_BUTTON = "Record",
    OPT_probeDoc_TIP = "Records Blizzard's built-in documentation of this client (the one /api shows): systems, functions with arguments and returns, events, tables and enumerations – compact, about 1 to 2 MB. Loads Blizzard's documentation addon for it; not in combat (like /ez probe doc).",
    OPT_probeStatus = "Data probe",
    PROBE_STATUS_BUTTON = "Show report",
    OPT_probeStatus_TIP = "Shows how much the data probe has recorded (entries and size in the file) and the report to copy: one line per query with its fields and a sample value, plus the latest events. The data reaches the disk only after /reload or logging out (like /ez probe status and /ez probe show).",
    OPT_probeClear = "Clear data probe",
    PROBE_CLEAR_BUTTON = "Clear probe",
    OPT_probeClear_TIP = "Deletes everything the data probe has recorded (queries, events, speed measurements, documentation) – after a confirmation. Settings and all other data stay (like /ez probe clear).",
    OPT_probeAuction = "Special probe: full auction house scan",
    OPT_probeAuction_TIP = "Only with the auction house open and only after a confirmation: requests all auctions once and checks whether the server serves that. Side effect: the server probably blocks the full scan for about 15 minutes afterwards (like /ez probe x2).",
    OPT_probeWaypoint = "Special probe: waypoint",
    OPT_probeWaypoint_TIP = "Only after a confirmation: briefly sets a waypoint on your own position, reads link and distance and then restores the old waypoint and the tracking (like /ez probe x3).",
    OPT_probeRecipes = "Special probe: unlearned recipes",
    OPT_probeRecipes_TIP = "Only with the profession window open and only after a confirmation: briefly switches on Blizzard's filter “show unlearned”, counts the recipes and switches it back at once (like /ez probe x4).",
    OPT_probeInspect = "Special probe: inspect a player",
    OPT_probeInspect_TIP = "Only with a player as target and only after a confirmation: asks the server for their gear and talents (like “Inspect”) and records how the answer is built – without names (like /ez probe inspect).",
    PROBE_SPECIAL_BUTTON = "Start",
    PROBE_ASK_Auction = "Special probe: request all auctions once?\nThe server probably blocks the full scan for about 15 minutes afterwards.",
    PROBE_ASK_Waypoint = "Special probe: briefly set a waypoint on your own position?\nYour current waypoint and the tracking are restored afterwards.",
    PROBE_ASK_Recipes = "Special probe: briefly switch on the filter “show unlearned recipes”?\nIt is switched back at once.",
    PROBE_ASK_Inspect = "Special probe: inspect your target?\nThis is a request to the server; names are not stored.",
