en.OPT_optInHints = "Hints about actions without a click"
de.OPT_optInHints_TIP = "Was ab Werk aus ist, weil es ohne deinen Klick Gold kostet, verkauft, Briefe sendet oder Blizzards Anzeigen umstellt (etwa Plunder verkaufen, automatisch reparieren, Briefe am Briefkasten), erklärt ezCollection einmal am passenden Blizzard-Fenster – mit Knopf „Einschalten“. Jede Funktion nur einmal je Account. Aus: keine solchen Hinweise mehr."
en.OPT_optInHints_TIP = "Whatever is off by default because it costs gold, sells, sends mail or changes Blizzard's displays without your click (such as selling junk, repairing automatically, letters at the mailbox) is explained once by ezCollection at the matching Blizzard window – with an “Enable” button. Each feature only once per account. Off: no such hints anymore."
de.OPTIN_HEAD = "ezCollection: Diese Abläufe sind ab Werk aus, weil sie ohne deinen Klick laufen. Du kannst sie nutzen – einschalten musst du sie selbst."
en.OPTIN_HEAD = "ezCollection: These actions are off by default because they run without your click. You can use them – but you have to turn them on yourself."
