en.OPTIN_SWITCHED_OFF = "ezCollection switched this off with the update (it was on before)."
de.OPTIN_WHERE = "Einstellung: Esc » Optionen » AddOns » ezCollection » %s."
en.OPTIN_WHERE = "Setting: Esc » Options » AddOns » ezCollection » %s."
de.OPTIN_FOOT = "Jeder Hinweis kommt nur einmal. Abschalten oder erneut zeigen: ezCollection » Erweitert."
en.OPTIN_FOOT = "Each hint comes only once. Turn them off or show them again: ezCollection » Advanced."
