-- Einführung (Wunsch des Nutzers vom 18.11.2026, W-1811-Einfuehrung; Werkzeuge/FirstStart.lua, Core.Intro): die
-- ezCollection als Ganzes, je Modul höchstens drei Sätze (was es tut, wo sein Knopf oder Reiter an Blizzards Fenster
-- sitzt) und das Einverständnis zu den Abläufen ohne Klick. Eine Stelle für alle Module (Leitlinie 2): die Module
-- liefern höchstens Schlüssel (OPT_<key>, OPTIN_<key>); fehlt einem Schalter ein OPTIN-Satz, steht hier INTRO_ON_<key>.
-- Befehle setzt ezCore über Core.SlashCmd ein (INTRO_CMD), keine festen Kurzbefehle.
for key, text in pairs({
    INTRO_TITLE = "Einführung",
    INTRO_DIALOG_TITLE = "ezCollection – Einführung",
    INTRO_ABOUT = "ezCollection ist eine Sammlung kleiner Module, die Blizzards eigene Fenster erweitern, statt sie zu ersetzen: Knöpfe, Reiter und Seitenteile sitzen direkt an Tasche, Karte, Briefkasten und Co. Jedes Modul lässt sich im Addon-Menü einzeln ein- und ausschalten, ebenso „ezCollection (Beiträge)“ mit geprüften Daten anderer Spieler; die Basis hält die gemeinsamen Daten aller Twinks. Was ohne dein Zutun Gold kostet, etwas sendet oder Blizzards Einstellungen umstellt, ist ab Werk aus; was nur auf deine eigene Handlung folgt, ist an – beides steht unter „Einverständnis“ und lässt sich dort umschalten.",
