    INTRO_MOD_ezCraft = "Unter den Zutaten in Blizzards Berufefenster steht der Abschnitt „ezCraft“; Reiter am rechten Rand öffnen Einkaufsliste, fehlende Rezepte und Abklingzeiten.",
    INTRO_MOD_ezGear = "Die Pfeile stehen an Taschenplätzen und Questbelohnungen; der Knopf „Sets“ sitzt links neben der Waffenhand im Charakterfenster.",
    INTRO_MOD_ezHeal = "Der Knopf „Vorlagen“ sitzt oben rechts in Blizzards Fenster „Klick-Zauber“; übernommen wird erst nach Vorschau und Rückfrage.",
    INTRO_MOD_ezLoot = "Der Knopf für schnelles Plündern sitzt oben links im Plündernfenster, die Beute steht auch im Tooltip der Gegner.",
    INTRO_MOD_ezMacro = "Der Knopf „ezMacro“ unten in Blizzards Makroverwaltung öffnet den Browser rechts daneben.",
    INTRO_MOD_ezMail = "Häkchen sitzen an jedem Brief, ein Pfeil neben „Alle öffnen“, Lupe und Schriftrolle als Seitenreiter am Postfenster.",
    INTRO_MOD_ezMap = "Der Knopf rechts neben Blizzards Pin-Knopf auf der Weltkarte bündelt Koordinaten, Lehrer, Dungeoneingänge und mehr; /way setzt Blizzards Kartenmarkierung.",
    INTRO_MOD_ezMerchant = "Alles sitzt in Blizzards Händler- und Lehrerfenster, „Was kommt wann“ als Reiter am Zauberbuch. Plunder verkaufen, Reparieren und Auffüllen ohne Klick sind ab Werk aus.",
    INTRO_MOD_ezPanel = "Die Leiste sitzt am oberen Bildschirmrand; jeder Baustein hat einen Tooltip und ein Rechtsklick-Menü.",
    INTRO_MOD_ezQuest = "Das Häkchen „Automatisch“ sitzt oben rechts im Questfenster, die Leveling-Route im Zahnrad-Menü am Questlog. Ergänzt Questie, ersetzt es nicht.",
    INTRO_MOD_ezSocial = "Alles sitzt in Blizzards „Gruppe suchen“, Freundes- und Gildenliste. Suchen startest nur du, ezSocial filtert und färbt.",
    INTRO_MOD_ezTalent = "Die Reiter „Vorlagen“ und „Empfehlung“ sitzen rechts am Talentfenster. Gültig wird eine Verteilung erst mit Blizzards eigenem Knopf „Übernehmen“.",
    -- Was passiert, wenn an – nur für Schalter, deren Modul keinen eigenen Satz OPTIN_<key> hat
    INTRO_ON_offlineQueue = "Nachrichten an Offline-Spieler warten und gehen von selbst hinaus, sobald der Empfänger online ist (höchstens 12 Versuche bzw. 24 Stunden).",
    INTRO_ON_cameraZoom = "Stellt Blizzards Kamera-Einstellung so um, dass du weiter herauszoomen kannst; beim Ausschalten kommt dein Wert von vorher zurück.",
    INTRO_ON_replyAway = "Antwortet von selbst auf Battle.net-Flüstern, während du abwesend bist (im Spiel antwortet Blizzard selbst).",
    INTRO_ON_replyCombat = "Antwortet im Kampf einmal von selbst auf Flüstern, mit deinem Antworttext für „Kampf“.",
    INTRO_ON_buyNextSelect = "Wählt nach einem Kauf im Auktionshaus die nächstgünstige Auktion vor; gekauft wird weiter nur mit deinem Klick.",
    INTRO_ON_scanOnOpen = "Startet beim Öffnen des Auktionshauses von selbst die Preis-Erfassung (mit Mindestabstand).",
    INTRO_ON_trackingRemember = "Stellt deine Auswahl in Blizzards Menü „Aufspüren“ nach dem Einloggen, nach /reload und nach dem Wiederbeleben wieder her (ohne Such-Zauber).",
    INTRO_ON_wayAutoClear = "Entfernt Blizzards Kartenmarkierung von selbst, kurz nachdem du angekommen bist.",
    INTRO_ON_routeWatch = "Setzt die Quest des nächsten Schritts der Leveling-Route von selbst in Blizzards Questverfolgung.",
    INTRO_ON_routeArrow = "Schaltet beim Weiterrücken der Route auch Blizzards Zielpfeil auf die neue Markierung (nur zusammen mit ezMaps Zielverfolgung).",
    INTRO_ON_rotation = "Zeigt mit angreifbarem Ziel, welche Aktion als Nächstes dran ist; gewirkt wird nur mit deinem Tastendruck.",
    INTRO_ON_oneClickUpdate = "Schreibt übernommene Ein-Klick-Makros neu, wenn sich Taschen, Stufe oder Zone ändern (nie im Kampf).",
    INTRO_ON_backupOnLogout = "Sichert beim Ausloggen die Makros dieses Charakters und die allgemeinen Makros, damit du sie auf einem Twink zurückholen kannst.",
    INTRO_ON_swapMount = "Legt beim Aufsteigen das Set „Reiten“ an, beim Absteigen kommt die vorherige Ausrüstung zurück (nie im Kampf).",
    INTRO_ON_swapFishing = "Legt beim Auswerfen das Set „Angeln“ an, nach einer Weile ohne Angeln kommt die vorherige Ausrüstung zurück.",
    INTRO_ON_fastLoot = "Plündert alles sofort, wenn Blizzards automatisches Plündern an ist – ohne Pause zwischen den Gegenständen.",
    INTRO_ON_makeRoom = "Rückt Blizzards Talentfenster zur Seite, solange das Seitenteil von ezTalent offen ist und daneben zu wenig Platz hat – nur außerhalb des Kampfes, danach wie vorher.",
    INTRO_ON_reserveTop = "Rückt Blizzards Fenster am oberen Bildschirmrand unter die Leiste von ezPanel (nie im Kampf).",
}) do de[key] = text end
for key, text in pairs({
    INTRO_TITLE = "Introduction",
    INTRO_DIALOG_TITLE = "ezCollection – introduction",
    INTRO_ABOUT = "ezCollection is a set of small modules that extend Blizzard's own windows instead of replacing them: buttons, tabs and side panels sit right at the bags, the map, the mailbox and so on. Each module can be turned on or off on its own in the addon menu, and so can “ezCollection (Contributions)” with checked data from other players; the base keeps the shared data of all your alts. Anything that costs gold, sends something or changes Blizzard's settings without you doing anything is off by default; what only follows your own action is on – both are listed under “Consent” and can be switched there.",
    INTRO_WHERE = "Settings: Esc » Options » AddOns » ezCollection. Every module has its page there, with the button “Introduction” at the top under “General”.",
    INTRO_CMD = "Command: %s – all commands: %s",
    INTRO_HELP_WORD = "help",
    INTRO_CMD_WORD = "intro",
    INTRO_HELP_CMD = "helpout",
    INTRO_PAGE_COUNT = "(%d/%d)",
    INTRO_FEATURE_LINE = "• %s",
    INTRO_MODULES_HEAD = "Modules (%d active):",
    INTRO_MODULE_OFF = "not active",
    INTRO_MODULE_ABSENT = "not installed",
    INTRO_CONSENT_HEAD = "Consent – things that run without a click",
    INTRO_CONSENT_OFF_HEAD = "Off by default – on only with your tick:",
    INTRO_CONSENT_ON_HEAD = "On by default – can be turned off here:",
    INTRO_STATE_ON = "on",
    INTRO_STATE_OFF = "off",
    INTRO_CONSENT_LINE = "[%s] %s: %s – %s",
    INTRO_CONSENT_WHERE = "Set the ticks: Settings » ezCollection » Introduction, section “Consent”. They are the same switches as on the module pages.",
    INTRO_CONSENT_PAGE = "%d of %d things that run without a click are now on. Under “Consent” this page lists all of them with their tick – the same switch as on the module's page, switching happens only out of combat.",
    INTRO_PAGE_CONSENT = "Without a click – a tick is your consent:",
    INTRO_AGREE_LABEL = "Agree to everything",
    INTRO_AGREE_BUTTON = "Agree to all",
    INTRO_AGREE_TIP = "Turns on what the running modules do without a click, all at once – and every feature that is off by default and that Blizzard's rules allow (such as the compact minimap). A question first shows what will happen; you can undo each one under “Consent” on the page “Introduction”.",
    INTRO_AGREE_RISK = "Not turned on because it risks Blizzard's rules or one of Blizzard's safeguards (sends, picks, uses up or pays without a click, puts things into Blizzard's buy and sell fields or lifts a safeguard): %s",
    INTRO_AGREE_CHOICE = "Not turned on, stays your choice (a matter of taste, a filter, help only some people need, consideration for another addon, explorer knowledge or a developer tool): %s",
    INTRO_AGREE_CONFIRM = "Agree to everything? ezCollection then turns on %d |4thing that runs:things that run; without a click:\n\n%s\n\nYou can undo each one: Settings » ezCollection » Introduction.",
    INTRO_AGREE_LINE = "%s: %s",
    INTRO_AGREE_NOTES = "Notes from the modules:\n%s",
    INTRO_AGREE_NOTE = "%s – note: %s",
    INTRO_NOTE_HEAD = "Note:",
    INTRO_AGREE_DONE = "Turned on %d |4thing that runs:things that run; without a click. Change them one by one: Settings » ezCollection » Introduction or %s.",
    INTRO_AGREE_NONE = "Everything “Agree to all” turns on is already on.",
    INTRO_AGREE_STAYS_OFF = "Still off, only by hand – %s. List: %s, “Short”.",
    INTRO_OFF_RISK = "risky %s",
    INTRO_OFF_CHOICE = "a matter of taste %s",
    INTRO_OFF_COUNT = "%s %d",
    INTRO_AGREE_NONE_SKIPPED = "Everything “Agree to all” turns on here is already on. Stays off because it has no effect in this game client: %s",
    INTRO_AGREE_SKIPPED = "Stays off because it has no effect in this game client: %s",
    INTRO_SET_BLOCKED = "“%s” has no effect in this game client and stays off. The tooltip on the page of %s says why.",
    INTRO_ROW_BLOCKED = "Has no effect in this game client – that is why it is grey. The tooltip on the page of %s says why.",
    INTRO_AGREE_FAILED = "Could not turn on (stays off), %d |4switch:switches;: %s. Try one by one: Settings » ezCollection » Introduction.",
    INTRO_LABEL_gatherOnly = "Gathering nodes: only what I can gather",
    INTRO_ALSO_HEAD = "Set along with your consent (features that are off by default):",
    INTRO_PAGE_ALSO = "Also set along with your consent (features that are off by default): %s",
    INTRO_AGREE_ALSO = "Also set (features that are off by default):\n%s",
    INTRO_AGREE_CONFIRM_ALSO = "Agree to everything? Everything that runs without a click is already on. ezCollection then also sets:\n\n%s\n\nYou can undo each one: Settings » ezCollection » Introduction.",
    INTRO_AGREE_ALSO_DONE = "Also set: %s.",
    INTRO_AGREE_ALSO_DONE_N = "Also turned on %d |4feature:features; that |4is:are; off by default. The list: %s, “Short”.",
    INTRO_ON_gatherOnly = "ezMap hides herbs and ores your skill is not high enough for yet (map filter “Gathering” » “By colour”: “Red – cannot gather yet” is then unticked).",
    INTRO_HELP_HEAD = "Help out",
    INTRO_HELP = "Voluntary: send the project your discoveries (gathering spots, loot, flight times) as an anonymous text. Once checked, they reach everyone with “ezCollection (Contributions)” and are marked “from contributions” there. Nothing is ever sent by itself – %s explains how.",
    INTRO_LABEL = "Introduction",
    INTRO_BUTTON = "Open",
    INTRO_TIP = "A short introduction to ezCollection and every module, plus your consent to everything that acts without a click – on one page or module by module.",
    INTRO_SHORT_LABEL = "Short: everything on one page",
    INTRO_SHORT_BUTTON = "Read",
    INTRO_SHORT_TIP = "Shows the overview of all modules and the list of things that run without a click, with their state, as text to read and copy, with the button “Agree to all” at the bottom. Only for reading – you decide with “Agree to all”, module by module (“One by one”) or with the ticks on this page under “Consent”.",
    INTRO_PAGES_LABEL = "One by one: module by module",
    INTRO_PAGES_BUTTON = "Start",
    INTRO_PAGES_TIP = "Walks through all modules with “Next” and “Back”: for each module, the Blizzard window it sits on opens (character, map, bags …; otherwise its settings page). A bubble next to it explains what it does and asks with ticks for your consent to everything it does without a click; the module's help bubbles come along right away.",
    INTRO_MODULES_HEADER = "Modules",
    INTRO_MODULES_HEADER_TIP = "One button per active module: it opens the module's page and explains it in a bubble next to it. The button “Introduction” at the top of every module page does the same.",
    INTRO_MODULE_BUTTON = "Show",
    INTRO_CONSENT_HEADER = "Consent: off by default",
    INTRO_CONSENT_HEADER_TIP = "These act without a click, cost gold, send something or change Blizzard's settings – that is why they are off by default. A tick turns on the same switch as on the module's page.",
    INTRO_ALSO_HEADER = "Set along with your consent",
    INTRO_ALSO_HEADER_TIP = "Features that are off by default and do not risk Blizzard's rules: “Agree to everything” sets them too. A tick turns on the same switch as on the module's page.",
    INTRO_CONSENT_ON_HEADER = "Things without a click: on by default",
    INTRO_CONSENT_ON_HEADER_TIP = "These are on by default because they only follow your own action or send nothing. You can turn them off here – the same switch as on the module's page.",
    INTRO_ROW_LABEL = "%s: %s",
    INTRO_ROW_TIP = "When on: %s\n\nThe same switch as on the page of %s.",
    INTRO_HELP_HEADER_TIP = "Voluntary: how you can send the project your discoveries. Nothing is ever sent by itself.",
    INTRO_OFFER_RESET_LABEL = "Offer of the introduction",
    INTRO_STATE_BUTTON = "Toggle",
    INTRO_STATE_ON = "“%s” is on now.",
    INTRO_STATE_OFF = "“%s” is off now.",
    INTRO_STATE_FAILED = "“%s” could not be toggled right now (dead, just logged in or refused by the game). Please try again in a moment.",
    INTRO_OFFER_RESET_BUTTON = "Show again",
    INTRO_OFFER_RESET_TIP = "Offers the introduction again with a help bubble at the next login.",
    INTRO_OFFER_RESET_DONE = "The introduction will be offered again at the next login.",
    INTRO_PAGE_LABEL = "Introduction",
    INTRO_PAGE_BUTTON = "Show",
    INTRO_PAGE_TIP = "Explains %s in a bubble at its Blizzard window or next to this page, with ticks for your consent; “Next” and “Back” walk through all modules.",
    INTRO_NEXT = "Next",
    INTRO_BACK = "Back",
    INTRO_DONE = "Done",
    INTRO_WHAT = "The introduction",
    INTRO_SET_WHAT = "Switching via the introduction",
    INTRO_OFF_WHERE = "“%s” can only be turned on here. To turn it off: %s",
    INTRO_OFFER = "New to ezCollection? Some modules can act without a click (sell, share, change settings) and need your consent. “Agree to all” turns everything on at once (with a question first), “Decide one by one” opens the modules in turn at Blizzard's windows, “Short” shows everything on one page.",
    INTRO_OFFER_SHORT = "Short",
    INTRO_OFFER_PAGES = "Decide one by one",
    INTRO_OFFER_LATER = "Later",
    INTRO_OFFER_LATER_DONE = "You can find the introduction any time under Settings » ezCollection » Introduction or with %s.",
    INTRO_CMD_USAGE = "%s: page “Introduction” – add “short”, “pages”, “all” (agree to everything, with a question first) or the name of a module (e.g. %s).",
    INTRO_MOD_ezAuction = "Everything sits in Blizzard's auction house; the button “Scan prices” is at the top left of the auction window. Auctionator is not needed.",
    INTRO_MOD_ezBag = "Groups and marks sit right in Blizzard's bag and bank; the button at the top right of the bag opens the ezBag window.",
    INTRO_MOD_ezBars = "The bars sit left of Blizzard's right bars; columns, rows and keys are set on ezBars' page.",
    INTRO_MOD_ezBuff = "The button appears right next to Blizzard's buff bar; in combat it disappears.",
    INTRO_MOD_ezChat = "The tab “Conversations” sits on the right of the chat tab bar, a side tab at the friends list.",
    INTRO_MOD_ezCombat = "The rotation is in the tab “Rotation” at the spellbook, and every helper has a button “Show” on ezCombat's page.",
    INTRO_MOD_ezCraft = "Below the reagents in Blizzard's profession window sits the section “ezCraft”; tabs on the right edge open the shopping list, missing recipes and cooldowns.",
    INTRO_MOD_ezGear = "The arrows sit on bag slots and quest rewards; the button “Sets” sits left of the main hand in the character window.",
    INTRO_MOD_ezHeal = "The button “Templates” sits at the top right of Blizzard's window “Click Casting”; nothing is applied before preview and question.",
    INTRO_MOD_ezLoot = "The button for fast looting sits at the top left of the loot window, the loot also shows in the enemy tooltip.",
    INTRO_MOD_ezMacro = "The button “ezMacro” at the bottom of Blizzard's macro window opens the browser next to it.",
    INTRO_MOD_ezMail = "Ticks sit on each letter, an arrow next to “Open All”, magnifier and scroll as side tabs at the mail window.",
    INTRO_MOD_ezMap = "The button right of Blizzard's pin button on the world map bundles coordinates, trainers, dungeon entrances and more; /way sets Blizzard's map pin.",
    INTRO_MOD_ezMerchant = "Everything sits in Blizzard's vendor and trainer windows, “What comes when” as a tab at the spellbook. Selling junk, repairing and restocking without a click are off by default.",
    INTRO_MOD_ezPanel = "The bar sits at the top of the screen; every block has a tooltip and a right-click menu.",
    INTRO_MOD_ezQuest = "The tick “Automatic” sits at the top right of the quest window, the leveling route in the gear menu at the quest log. Complements Questie, does not replace it.",
    INTRO_MOD_ezSocial = "Everything sits in Blizzard's “Group Finder”, friends list and guild roster. Only you start a search, ezSocial filters and colors.",
    INTRO_MOD_ezTalent = "The tabs “Templates” and “Advice” sit on the right of the talent window. A build only takes effect with Blizzard's own button “Apply”.",
    INTRO_ON_offlineQueue = "Messages to offline players wait and go out by themselves as soon as the recipient is online (at most 12 tries or 24 hours).",
    INTRO_ON_cameraZoom = "Changes Blizzard's camera setting so you can zoom out further; turning it off restores your previous value.",
    INTRO_ON_replyAway = "Replies by itself to Battle.net whispers while you are away (in the game Blizzard replies itself).",
    INTRO_ON_replyCombat = "In combat, replies once by itself to whispers, with your reply text for “combat”.",
    INTRO_ON_buyNextSelect = "After a purchase at the auction house, selects the next cheapest auction; buying still needs your click.",
    INTRO_ON_scanOnOpen = "Starts the price scan by itself when the auction house opens (with a minimum gap).",
    INTRO_ON_trackingRemember = "Restores your choice in Blizzard's “Tracking” menu after logging in, after /reload and after resurrecting (without search spells).",
    INTRO_ON_wayAutoClear = "Removes Blizzard's map pin by itself shortly after you arrive.",
    INTRO_ON_routeWatch = "Puts the quest of the next leveling route step into Blizzard's quest tracker by itself.",
    INTRO_ON_routeArrow = "When the route moves on, also switches Blizzard's waypoint arrow to the new pin (only together with ezMap's waypoint tracking).",
    INTRO_ON_rotation = "With an attackable target, shows which action is next; casting still needs your key press.",
    INTRO_ON_oneClickUpdate = "Rewrites applied one-click macros when bags, level or zone change (never in combat).",
    INTRO_ON_backupOnLogout = "On logout, saves this character's macros and the general macros so you can restore them on an alt.",
    INTRO_ON_swapMount = "Puts on the set “Riding” when you mount, your previous gear comes back when you dismount (never in combat).",
    INTRO_ON_swapFishing = "Puts on the set “Fishing” when you cast, your previous gear comes back after a while without fishing.",
    INTRO_ON_fastLoot = "Loots everything at once when Blizzard's auto loot is on – without the pause between items.",
    INTRO_ON_makeRoom = "Moves Blizzard's talent window aside while ezTalent's side panel is open and there is too little room next to it – only out of combat, restored afterwards.",
    INTRO_ON_reserveTop = "Moves Blizzard's windows at the top of the screen below ezPanel's bar (never in combat).",
}) do en[key] = text end
de.CMD_HELP[#de.CMD_HELP + 1] = "  /ez einführung – Einführung: alle Module kurz und dein Einverständnis (dazu „kurz“, „einzeln“ oder ein Modul)"
en.CMD_HELP[#en.CMD_HELP + 1] = "  /ez intro – introduction: all modules in brief and your consent (add “short”, “pages” or a module)"

-- Einstellungs-Prüfung vom 19.11.2026 (Entscheidung des Nutzers „Ja, alle umsetzen“): Abhängigkeiten der Einstellungen,
-- gemeinsame Schalter mehrerer Module, zusammengelegte und umbenannte Schalter von ezCore, Mitschnitt ohne Lauf
for key, text in pairs({
    SETTINGS_NEEDS_PARENT = "Wirkt nur, solange „%s“ an ist – darum gerade grau.",
    SETTINGS_NEEDS_PARENT_ANY = "Wirkt erst, wenn der übergeordnete Schalter an ist – darum gerade grau.",
    SETTINGS_SHARED_NOTE = "Ein Schalter für mehrere Module: Er steht auch auf der Seite „ezCollection“ (Abschnitt „Gemeinsame Schalter“ bzw. „Tooltip“ oder „Auktionshaus“) und gilt überall gleich.",
    SHARED_HEADER = "Gemeinsame Schalter",
    SHARED_HEADER_TIP = "Schalter, die mehrere Module lesen. Jeder steht hier einmal und als Spiegel auf den Seiten der Module, die ihn nutzen – ein Klick an einer Stelle gilt überall. Eine Zeile erscheint nur, solange ein Modul läuft, das sie liest.",
    OPT_vendorAutoSell = "Plunder beim Händler verkaufen",
    OPT_vendorAutoSell_TIP = "Verkauft beim Ansprechen eines Händlers von selbst, was als Plunder gilt (Graues; mit ezBag nach ezBags Gruppen, Schlössern und Markierungen). Teile, die laut ezGear besser sind als dein Angelegtes, bleiben – außer du hast sie als Plunder markiert. Es verkauft ezBag, ohne ezBag ezMerchant. Nie im Kampf, Shift beim Ansprechen überspringt, Blizzards Reiter „Rückkauf“ holt Verkauftes zurück. Ab Werk aus.",
    OPT_vendorRepairAuto = "Automatisch reparieren",
    OPT_vendorRepairAuto_TIP = "Repariert beim Händler von selbst alles, was er reparieren kann. Es repariert ezMerchant, ohne ezMerchant ezPanel. Nie im Kampf (danach, wenn der Händler noch offen ist). Ab Werk aus.",
    OPT_vendorRepairGuild = "Reparieren: zuerst mit Gildengeld",
    OPT_vendorRepairGuild_TIP = "Zahlt Reparaturen zuerst aus der Gildenbank, soweit Tageslimit und Guthaben reichen; den Rest zahlst du selbst. Gilt für die automatische Reparatur und für den Knopf „Jetzt reparieren“. Ab Werk aus.",
    OPT_vendorRepairReport = "Reparieren: Kosten im Chat melden",
    OPT_vendorRepairReport_TIP = "Nennt nach einer automatischen Reparatur die Kosten und wer gezahlt hat. Zu wenig Gold meldet ezCollection immer, eine Reparatur von Hand auch. Ab Werk an.",
    OPT_markItemLevel = "Itemlevel auf Ausrüstung",
    OPT_markItemLevel_TIP = "Zeigt das Itemlevel auf Waffen und Rüstung – an ezBags Taschenplätzen und in ezLoots Plündern- und Würfelfenster (ein Schalter für beide). Ab Werk an.",
    OPT_markBoe = "„BoE“ auf Ausrüstung",
    OPT_markBoe_TIP = "Zeigt „BoE“ auf Ausrüstung, die erst beim Anlegen bindet – an ezBags Taschenplätzen (nur ungebunden) und in ezLoots Plündern- und Würfelfenster (ein Schalter für beide). Ab Werk an.",
    INTRO_ON_autoSell = "Verkauft beim Ansprechen eines Händlers von selbst deinen Plunder (es verkauft ezBag, ohne ezBag ezMerchant; nie im Kampf).",
    INTRO_ON_repairAuto = "Repariert beim Händler von selbst deine Ausrüstung und zahlt dafür Gold (es repariert ezMerchant, ohne ezMerchant ezPanel; nie im Kampf).",
    VENDOR_REPAIR_MIXED = "„Automatisch reparieren“ gilt jetzt für das ganze Konto; ezPanels Profile standen dafür je Charakter verschieden.",
    INTRO_OFFER_NEVER = "Nicht mehr anbieten",
    INTRO_OFFER_NEVER_DONE = "Die Einführung wird nicht mehr angeboten. Du findest sie jederzeit über %s.",
    DEBUG_NONE_HEAD = "ezCollection %s – in dieser Sitzung lief noch kein Mitschnitt.",
    DEBUG_NONE_HOW = "So geht es: Einstellungen » ezCollection » Erweitert » „Mitschnitt“ – „Starten / Stoppen“ einmal klicken (oder /ez debug), kurz weiterspielen, dann denselben Knopf noch einmal klicken: Der Bericht erscheint von selbst.",
    COMFORT_GRAPHICS_HEADER = "Grafik",
    COMFORT_GRAPHICS_HEADER_TIP = "Grafik-Werte des Spiels, die Blizzards Grafik-Einstellungen auf Forever nicht einzeln anbieten. Sie können Leistung kosten; eine Grafikstufe in Blizzards Einstellungen kann sie überschreiben.",
}) do de[key] = text end
for key, text in pairs({
    SETTINGS_NEEDS_PARENT = "Only takes effect while “%s” is on – that is why it is grey right now.",
    SETTINGS_NEEDS_PARENT_ANY = "Only takes effect once the switch above it is on – that is why it is grey right now.",
    SETTINGS_SHARED_NOTE = "One switch for several modules: it is also on the page “ezCollection” (section “Shared switches”, “Tooltip” or “Auction house”) and works the same everywhere.",
    SHARED_HEADER = "Shared switches",
    SHARED_HEADER_TIP = "Switches read by several modules. Each one is here once and mirrored on the pages of the modules that use it – a click in one place applies everywhere. A row only appears while a module that reads it is running.",
    OPT_vendorAutoSell = "Sell junk at vendors",
    OPT_vendorAutoSell_TIP = "When you talk to a vendor, sells whatever counts as junk by itself (grey items; with ezBag following ezBag's groups, locks and marks). Gear ezGear rates better than what you wear stays, unless you marked it as junk. ezBag sells, without ezBag ezMerchant does. Never in combat, Shift while talking to the vendor skips it, Blizzard's tab “Buyback” gets sold items back. Off by default.",
    OPT_vendorRepairAuto = "Repair automatically",
    OPT_vendorRepairAuto_TIP = "Repairs everything the vendor can repair by itself. ezMerchant repairs, without ezMerchant ezPanel does. Never in combat (afterwards, if the vendor is still open). Off by default.",
    OPT_vendorRepairGuild = "Repair: guild funds first",
    OPT_vendorRepairGuild_TIP = "Pays repairs from the guild bank first, as far as the daily limit and the bank's funds allow; you pay the rest yourself. Applies to automatic repairs and to the button “Repair now”. Off by default.",
    OPT_vendorRepairReport = "Repair: report costs in chat",
    OPT_vendorRepairReport_TIP = "After an automatic repair, names the costs and who paid. Not enough gold is always reported, and so is a repair by hand. On by default.",
    OPT_markItemLevel = "Item level on gear",
    OPT_markItemLevel_TIP = "Shows the item level on weapons and armor – on ezBag's bag slots and in ezLoot's loot and roll windows (one switch for both). On by default.",
    OPT_markBoe = "“BoE” on gear",
    OPT_markBoe_TIP = "Shows “BoE” on gear that only binds when equipped – on ezBag's bag slots (unbound only) and in ezLoot's loot and roll windows (one switch for both). On by default.",
    INTRO_ON_autoSell = "Sells your junk by itself when you talk to a vendor (ezBag sells, without ezBag ezMerchant; never in combat).",
    INTRO_ON_repairAuto = "Repairs your gear by itself at a vendor and pays gold for it (ezMerchant repairs, without ezMerchant ezPanel; never in combat).",
    VENDOR_REPAIR_MIXED = "“Repair automatically” now applies to the whole account; ezPanel's profiles had it set differently per character.",
    INTRO_OFFER_NEVER = "Don't offer again",
    INTRO_OFFER_NEVER_DONE = "The introduction will not be offered again. You can always find it via %s.",
    DEBUG_NONE_HEAD = "ezCollection %s – no recording has run in this session yet.",
    DEBUG_NONE_HOW = "How it works: Settings » ezCollection » Advanced » “Recording” – click “Start / stop” once (or /ez debug), keep playing for a bit, then click the same button again: the report appears by itself.",
    COMFORT_GRAPHICS_HEADER = "Graphics",
    COMFORT_GRAPHICS_HEADER_TIP = "Graphics values of the game that Blizzard's graphics settings on Forever do not offer one by one. They may cost performance; a graphics level in Blizzard's settings can overwrite them.",
}) do en[key] = text end
-- umbenannt bzw. neu gefasst (Einstellungs-Prüfung 19.11.2026, Abschnitte 2–4)
de.OPT_betaHints = "Fehlerbericht-Knopf und Umfragen ausblenden"
en.OPT_betaHints = "Hide bug report button and surveys"
de.OPT_gamepad = "Controller-Steuerung"
en.OPT_gamepad = "Controller input"
de.OPT_autoUnshift_TIP = "Druiden und Schamanen verlassen ihre Gestalt, wenn ein Zauber oder Gegenstand das verlangt. Aus: du bleibst in der Gestalt und bekommst Blizzards Fehlermeldung."
en.OPT_autoUnshift_TIP = "Druids and shamans leave their form when a spell or item requires it. Off: you stay in your form and get Blizzard's error message."
de.OPT_ttRelation = "Gilde und Freunde"
en.OPT_ttRelation = "Guild and friends"
de.OPT_ttRelation_TIP = "Zeigt bei Spielern den Rang in ihrer Gilde und ob sie dein Freund, Battle.net-Freund oder Gildenmitglied sind."
en.OPT_ttRelation_TIP = "Shows a player's guild rank and whether they are your friend, Battle.net friend or guild member."
de.OPT_ttItemLevel = "Itemlevel und Spezialisierung"
en.OPT_ttItemLevel = "Item level and specialization"
de.OPT_ttItemLevel_TIP = "Zeigt das durchschnittliche Itemlevel der angelegten Ausrüstung – Blizzards eigene Zahl wie im Betrachten-Fenster – und die Spezialisierung: bei dir der Talentbaum mit den meisten Punkten (ohne Talentpunkte keine Zeile), bei anderen nur, falls das Spiel eine nennt. Bei anderen Spielern liest ezCore beides außerhalb des Kampfes über „Betrachten“ (in Reichweite) und merkt es sich zehn Minuten; die Zeilen erscheinen, sobald die Antwort da ist."
en.OPT_ttItemLevel_TIP = "Shows the average item level of the equipped gear – Blizzard's own number, as in the inspect window – and the specialization: for you the talent tree with the most points (no line without talent points), for others only if the game names one. For other players ezCore reads both out of combat via inspect (in range) and remembers them for ten minutes; the lines appear once the answer arrives."
de.OPT_ttIDs = "IDs in Tooltips (NPC, Quest)"
en.OPT_ttIDs = "IDs in tooltips (NPC, quest)"
de.OPT_ttIDs_TIP = "Zeigt die ID von NPCs im Tooltip und – mit ezQuest – die ID jeder Quest unten im Tooltip des Questlogs (z. B. für Fehlermeldungen, Makros oder Datenbanken). Ein Schalter für ezCore und ezQuest. Ab Werk aus."
en.OPT_ttIDs_TIP = "Shows the ID of NPCs in their tooltip and – with ezQuest – each quest's ID at the bottom of its tooltip in the quest log (e.g. for bug reports, macros or databases). One switch for ezCore and ezQuest. Off by default."
de.OPT_optInHints = "Hinweise und Angebote zeigen"
en.OPT_optInHints = "Show hints and offers"
de.OPT_optInHints_TIP = "Einmalige Hinweise von ezCollection: Was ab Werk aus ist, weil es ohne deinen Klick Gold kostet, verkauft, Briefe sendet oder Blizzards Anzeigen umstellt, erklärt eine Blase am passenden Blizzard-Fenster – mit Knopf „Einschalten“ (jede Funktion einmal je Account). Dazu das Angebot der Einführung nach dem Einloggen und der Hinweis „Mithelfen“ nach einigen Anmeldungen. Aus: keine dieser Blasen mehr. Einzeln abwählen: „Nicht mehr zeigen“ bzw. „Nicht mehr anbieten“ in der Blase."
en.OPT_optInHints_TIP = "One-time hints from ezCollection: whatever is off by default because it costs gold, sells, sends mail or changes Blizzard's displays without your click is explained by a bubble at the matching Blizzard window – with an “Enable” button (each feature once per account). Also the offer of the introduction after logging in and the hint “Help out” after a few logins. Off: none of these bubbles anymore. To turn off one of them: “Don't show again” or “Don't offer again” in the bubble."
de.TOURS_ALL_LABEL = "Alle Hinweise und Erklärblasen"
en.TOURS_ALL_LABEL = "All hints and help bubbles"
de.TOURS_ALL_TIP = "Setzt die Erklärblasen aller Module, den Rundgang „Erster Start“, die Hinweise auf Abläufe ohne Klick, das Angebot der Einführung und den Hinweis „Mithelfen“ zurück. Sie erscheinen beim nächsten passenden Anlass wieder (Fenster öffnen bzw. Einloggen), solange „Hinweise und Angebote zeigen“ an ist."
en.TOURS_ALL_TIP = "Resets the help bubbles of all modules, the \"First start\" tour, the hints about actions without a click, the offer of the introduction and the hint \"Help out\". They appear again at the next matching occasion (opening the window or logging in) as long as “Show hints and offers” is on."
de.TOURS_ALL_ASK = "Alle Hinweise und Erklärblasen erneut zeigen?"
en.TOURS_ALL_ASK = "Show all hints and help bubbles again?"
de.TOURS_ALL_DONE = "Die Hinweise und Erklärblasen erscheinen wieder (%d |4Satz:Sätze; zurückgesetzt)."
en.TOURS_ALL_DONE = "The hints and help bubbles will appear again (%d |4set:sets; reset)."
de.OPT_dataCollect = "Erlebtes in der Datenbank sammeln"
en.OPT_dataCollect = "Collect what you experience in the database"
de.OPT_explorer = "Entdecker-Wissen zeigen (Spoiler)"
en.OPT_explorer = "Show explorer knowledge (spoilers)"
de.OPT_explorer_TIP = "Zeigt auch, was man selbst entdecken soll: seltene Gegner, Buch-Fundorte, enthüllte Gegenstände (gilt auch für ezMaps Kisten und seltene Gegner). Gesammelt wird es auch ohne diesen Schalter; ab Werk aus."
en.OPT_explorer_TIP = "Also shows what you are meant to discover yourself: rare enemies, book locations, revealed items (also applies to ezMap's chests and rare enemies). It is collected without this switch as well; off by default."
-- Preisverlauf: nur noch die Auswahl (Nr. 51); OPT_priceWeeks bleibt als Name dieser Auswahl für ezAuctions Hinweis
de.OPT_priceWeeks = de.OPT_priceWeeksMax
en.OPT_priceWeeks = en.OPT_priceWeeksMax
de.OPT_priceWeeksMax_TIP = "Für beobachtete Gegenstände (Taschen, eigene Auktionen, Listen) hält der Verlauf %d Tage. Ältere Tage werden zu Wochenpunkten verdichtet (Tief, Hoch, Median, Menge) – höchstens so viele Wochen wie hier gewählt (bis %d). 0: keine Wochenpunkte, ältere Tage fallen weg; gemerkte Wochen bleiben liegen. Ab Werk 26."
en.OPT_priceWeeksMax_TIP = "For watched items (bags, own auctions, lists) the history keeps %d days. Older days are condensed into weekly points (low, high, median, quantity) – at most as many weeks as chosen here (up to %d). 0: no weekly points, older days are dropped; weeks already kept stay. 26 by default."
-- Monatspunkte (Entscheidung des Nutzers vom 21.11.2026, „Beides bauen“)
de.OPT_priceMonthsMax = "Preisverlauf: Monate behalten"
en.OPT_priceMonthsMax = "Price history: months to keep"
de.OPT_priceMonthsMax_TIP = "Wochen, die über die behaltenen Wochen hinaus alt werden, werden zu Monatspunkten verdichtet (Tief, Hoch, Median der Wochen, Menge) – höchstens so viele Monate wie hier gewählt (bis %d). Damit zeigt ezAuctions Seitenteil „Markt“ auch Monate und Jahre, ohne den Graph zu stauchen. 0: keine Monatspunkte, ältere Wochen fallen weg. Monate entstehen aus Wochen: Mit „Wochen behalten“ auf 0 kommen keine dazu. Ab Werk 24."
en.OPT_priceMonthsMax_TIP = "Weeks that grow older than the weeks kept are condensed into monthly points (low, high, median of the weeks, quantity) – at most as many months as chosen here (up to %d). This lets ezAuction's \"Market\" side panel show months and years without squeezing the graph. 0: no monthly points, older weeks are dropped. Months are built from weeks: with \"weeks to keep\" at 0 none are added. 24 by default."
de.OPT_priceOpts_worthBag_NOTE = "Gilt auch an ezBags Plätzen (Tasche, Bank, ezBag-Fenster) – ein Schalter für ezCore und ezBag (zusätzlich /ezbag auktionswert). Beim Händler gilt das Kästchen „beim Händler“."
en.OPT_priceOpts_worthBag_NOTE = "Also applies on ezBag's slots (bags, bank, ezBag window) – one switch for ezCore and ezBag (also /ezbag auktionswert). At a vendor the box \"at vendors\" applies."
de.GATHER_FORGET_KIND_TIP = "Öffnet eine Auswahl der Arten mit der Zahl deiner Fundorte; nach der Wahl und einer Rückfrage entfernt es alle eigenen Fundorte dieser Art auf allen Karten. Beute und Erträge bleiben."
en.GATHER_FORGET_KIND_TIP = "Opens a list of the kinds with the number of your gathering spots; after choosing one and confirming, removes all your own spots of that kind on every map. Loot and yields stay."
de.GATHER_FORGET_ZONE_TIP = "Öffnet eine Auswahl der Zonen mit der Zahl deiner Fundorte („hier“ ist die Zone, in der du bist); nach der Wahl und einer Rückfrage leert es diese Zone. Beute und Erträge bleiben."
en.GATHER_FORGET_ZONE_TIP = "Opens a list of the zones with the number of your gathering spots (“here” is the zone you are in); after choosing one and confirming, empties that zone. Loot and yields stay."
de.DEBUG_REPORT_TIP = "Zeigt den Bericht des letzten Mitschnitts zum Kopieren, ohne einen neuen zu starten – auch nachdem er nach fünf Minuten von selbst geendet hat (wie /ez debug zeigen). Lief noch keiner, sagt er, wie man startet: zuerst „Starten / Stoppen“."
en.DEBUG_REPORT_TIP = "Shows the report of the last recording to copy, without starting a new one – also after it ended by itself after five minutes (like /ez debug show). If none has run yet, it says how to start one: “Start / stop” first."

-- Nachfrage nach einem Update (Auftrag des Nutzers vom 23.11.2026; Werkzeuge/ConsentNews.lua, Core.Intro)
for key, text in pairs({
    INTRO_NEWS_LABEL = "Neu seit dem Update",
    INTRO_NEWS_BUTTON = "Zeigen",
    INTRO_NEWS_TIP = "Zeigt in einer Blase, was mit einem Update dazugekommen ist: Funktionen, die dein Einverständnis brauchen, und neue, die ab Werk an sind (Häkchen gesetzt, abwählbar). Je Funktion ein Häkchen (was sie tut, steht im Tooltip), dazu „Alle annehmen“. Nach einem Update fragt ezCollection einmal von selbst danach, kurz nach dem Einloggen; was du schon entschieden hast, bleibt, wie es ist. Ist nichts Neues offen, stehen die Funktionen der letzten Nachfrage da.",
    INTRO_NEWS_HEAD = "Neu seit dem Update",
    INTRO_NEWS = "%d |4neue Funktion braucht:neue Funktionen brauchen; dein Einverständnis. Ein Häkchen schaltet eine ein, „Alle annehmen“ alle zugleich; was eine tut, steht im Tooltip. „Fertig“ oder das X lässt den Rest aus – gefragt wird erst wieder, wenn ein Update Neues bringt.",
    INTRO_NEWS_ON = "%d |4neue Funktion ist:neue Funktionen sind; ab Werk an (Häkchen gesetzt). Ein weggenommenes Häkchen schaltet sie aus; „Alle annehmen“ und „Fertig“ lassen sie, wie sie angehakt sind.",
    INTRO_NEWS_ON_LABEL = "%s (ab Werk an)",
    INTRO_NEWS_AGAIN = "Diese Funktionen standen in der letzten Nachfrage. Ein Häkchen schaltet eine ein oder aus, „Alle annehmen“ schaltet alle ein, die dein Einverständnis brauchen; was eine tut, steht im Tooltip.",
    INTRO_NEWS_FIRST = "Ab jetzt fragt ezCollection nach jedem Update nach dem, was neu dazukommt. Zum Start einmal alles, was dein Einverständnis braucht und bei dir aus ist (%d). Ein Häkchen schaltet eine Funktion ein, „Alle annehmen“ alle zugleich; was eine tut, steht im Tooltip. „Fertig“ oder das X lässt den Rest aus.",
    INTRO_NEWS_NEXT_TIP = "Zeigt die nächsten Funktionen dieser Liste. „Alle annehmen“ gilt für alle Seiten.",
    INTRO_NEWS_RISK = "Nicht bei „Alle annehmen“ (riskiert Blizzards Regeln, nur per Häkchen): %s",
    INTRO_NEWS_ALL = "Alle annehmen",
    INTRO_NEWS_ALL_TIP = "Schaltet ein, was Blizzards Regeln erlauben:\n%s",
    INTRO_NEWS_ALL_ON = "Was ab Werk an ist, bleibt, wie du es angehakt hast.",
    INTRO_NEWS_ALL_KEEP = "Schließt die Liste; nichts ist einzuschalten. Was ab Werk an ist, bleibt, wie du es angehakt hast.",
    INTRO_NEWS_CLOSE = "Fertig",
    INTRO_NEWS_CLOSE_TIP = "Schließt die Liste. Was du nicht angehakt hast, bleibt aus, was angehakt ist, bleibt an; gefragt wird erst wieder, wenn ein Update Neues bringt. Wieder zeigen: Einstellungen » ezCollection » Einführung, „Neu seit dem Update“.",
    INTRO_NEWS_DONE = "Neu eingeschaltet: %s.",
    INTRO_NEWS_LATER = "%d |4Funktion bleibt:Funktionen bleiben; aus. Einschalten jederzeit: Einstellungen » ezCollection » Einführung, „Neu seit dem Update“.",
    INTRO_NEWS_NONE = "Seit dem letzten Update ist nichts dazugekommen, nach dem zu fragen wäre. Alle Schalter, die dein Einverständnis brauchen, stehen unter Einstellungen » ezCollection » Einführung, „Einverständnis“.",
}) do de[key] = text end
for key, text in pairs({
    INTRO_NEWS_LABEL = "New since the update",
    INTRO_NEWS_BUTTON = "Show",
    INTRO_NEWS_TIP = "Shows in a bubble what an update added: features that need your consent, and new ones that are on by default (ticked, untick to turn off). A tick for each feature (its tooltip says what it does) and “Accept all”. After an update ezCollection asks about them once by itself, shortly after logging in; whatever you already decided stays as it is. With nothing new pending, it shows the features of the last question.",
    INTRO_NEWS_HEAD = "New since the update",
    INTRO_NEWS = "%d new |4feature needs:features need; your consent. A tick turns one on, “Accept all” turns them all on; the tooltip says what each one does. “Done” or the X leaves the rest off – you are only asked again when an update brings something new.",
    INTRO_NEWS_ON = "%d new |4feature is:features are; on by default (ticked). Unticking turns one off; “Accept all” and “Done” leave them as ticked.",
    INTRO_NEWS_ON_LABEL = "%s (on by default)",
    INTRO_NEWS_AGAIN = "These features were in the last question. A tick turns one on or off, “Accept all” turns on all that need your consent; the tooltip says what each one does.",
    INTRO_NEWS_FIRST = "From now on ezCollection asks after every update about what is new. To start, once everything that needs your consent and is off for you (%d). A tick turns a feature on, “Accept all” turns them all on; the tooltip says what each one does. “Done” or the X leaves the rest off.",
    INTRO_NEWS_NEXT_TIP = "Shows the next features of this list. “Accept all” applies to all pages.",
    INTRO_NEWS_RISK = "Not included in “Accept all” (risks Blizzard's rules, tick only): %s",
    INTRO_NEWS_ALL = "Accept all",
    INTRO_NEWS_ALL_TIP = "Turns on what Blizzard's rules allow:\n%s",
    INTRO_NEWS_ALL_ON = "What is on by default stays as you ticked it.",
    INTRO_NEWS_ALL_KEEP = "Closes the list; there is nothing to turn on. What is on by default stays as you ticked it.",
    INTRO_NEWS_CLOSE = "Done",
    INTRO_NEWS_CLOSE_TIP = "Closes the list. Whatever you did not tick stays off, whatever is ticked stays on; you are only asked again when an update brings something new. Show again: Settings » ezCollection » Introduction, “New since the update”.",
    INTRO_NEWS_DONE = "Newly turned on: %s.",
    INTRO_NEWS_LATER = "%d |4feature stays:features stay; off. Turn on any time: Settings » ezCollection » Introduction, “New since the update”.",
    INTRO_NEWS_NONE = "The last update added nothing to ask about. All switches that need your consent are under Settings » ezCollection » Introduction, “Consent”.",
}) do en[key] = text end

Core.L = Core.NewLocale(de, en)
ns.L = Core.L
